// Saca del JSON de Meta solo lo que usa el flujo y valida que tenga forma de WhatsApp.
const value = $json.body?.entry?.[0]?.changes?.[0]?.value;
const base = { recibido_en: new Date().toISOString() };
if (!value) {
  return { json: { ...base, tipo_evento: 'invalido', motivo: 'Falta body.entry[0].changes[0].value: no es un evento de WhatsApp' } };
}
const msg = value.messages?.[0];
if (!msg) {
  // Meta también avisa "entregado" y "leído" (value.statuses) sin mensaje: no se responde.
  return { json: { ...base, tipo_evento: 'estado', motivo: 'Aviso de estado sin mensaje' } };
}
const texto = (msg.text?.body ?? '').trim().slice(0, 1500);
const numero = texto.match(/\b4\d{10}\b/);   // número de envío: 11 dígitos que empiezan con 4
return { json: {
  ...base,
  tipo_evento: msg.type === 'text' && texto ? 'texto' : 'sin_texto',
  telefono: msg.from,
  nombre_perfil: value.contacts?.[0]?.profile?.name ?? '',
  wamid: msg.id,
  tipo_mensaje: msg.type,
  texto,
  numero_envio_detectado: numero ? numero[0] : ''
} };

// El agente termina con 7 líneas "CAMPO: valor" (ACCION, TIPO, NUMERO_ENVIO, SELLER, PRIORIDAD, RESUMEN, RESPUESTA).
// Las pasamos a un JSON y lo validamos contra el esquema. Si algo no cierra, sale con
// accion = INVALIDO y el Switch lo manda al respaldo.
const ESQUEMA = {"type": "object", "properties": {"accion": {"type": "string", "enum": ["RESPONDER", "CARGAR_CASO", "DERIVAR"]}, "respuesta": {"type": "string", "description": "Texto para el seller por WhatsApp"}, "tipo": {"type": "string", "enum": ["consulta", "reclamo", "gestion", "comercial", "otro"]}, "numero_envio": {"type": "string"}, "seller": {"type": "string"}, "resumen": {"type": "string"}, "prioridad": {"type": "string", "enum": ["alta", "media", "baja"]}}, "required": ["accion", "respuesta", "tipo"]};
const texto = String($json.output ?? '').replace(/\*\*/g, '');   // por si el modelo pone negritas
let o = {};
let actual = null;
for (const linea of texto.split('\n')) {
  const m = linea.match(/^\s*(ACCION|TIPO|NUMERO_ENVIO|SELLER|PRIORIDAD|RESUMEN|RESPUESTA)\s*:\s?(.*)$/i);
  if (m) { actual = m[1].toLowerCase(); o[actual] = m[2]; }
  else if (actual === 'respuesta' && linea.trim()) o.respuesta += ' ' + linea.trim();  // respuesta en 2 renglones
}
if (o.accion) o.accion = o.accion.trim().toUpperCase();
if (o.tipo) o.tipo = o.tipo.trim().toLowerCase();
if (o.prioridad) o.prioridad = o.prioridad.trim().toLowerCase();
if (o.numero_envio) o.numero_envio = o.numero_envio.replace(/\D/g, '');
const props = ESQUEMA.properties;
const errores = [];
if (!Object.keys(o).length) errores.push('no tiene el formato de 7 líneas');
else {
  for (const c of ESQUEMA.required) if (!o[c]) errores.push('falta ' + c);
  for (const [c, def] of Object.entries(props)) {
    if (o[c] == null) o[c] = '';
    o[c] = String(o[c]).trim();
    if (def.enum && o[c] && !def.enum.includes(o[c])) errores.push(c + ' inválido: ' + o[c]);
  }
}
if (errores.length) return { json: { output: { accion: 'INVALIDO' }, error: { message: 'Salida del agente inválida (' + errores.join(', ') + '): ' + texto.slice(0, 150) } } };
return { json: { output: o } };

// El modelo no respondió (o devolvió algo que no es JSON) después de 2 intentos.
// No dejamos al seller sin respuesta: derivamos a un humano y el caso queda registrado.
const err = $json.error?.message ?? $json.error ?? 'sin detalle';
return { json: { output: {
  accion: 'DERIVAR',
  respuesta: 'Tuvimos un problema técnico para responderte. Ya le paso tu consulta a un operador y te escribe por acá.',
  tipo: 'otro',
  numero_envio: $('Normalizar mensaje').item.json.numero_envio_detectado,
  seller: '',
  resumen: 'Falla del modelo: ' + String(err).slice(0, 200),
  prioridad: 'media',
  origen: 'error_ia'
} } };

// Arma la fila del caso y valida antes de escribir en la planilla.
const o = $json.output;
const n = $('Normalizar mensaje').item.json;
const numeroOk = /^4\d{10}$/.test(o.numero_envio ?? '');
let accion = o.accion;
let respuesta = o.respuesta;
let nota = '';
if (accion === 'CARGAR_CASO' && !numeroOk) {
  // El agente quiso cargar un caso sin un número válido: no lo cargamos como reclamo de un envío.
  accion = 'DERIVAR';
  nota = '[Validación: número de envío inválido] ';
  respuesta = 'Esto lo tiene que ver un operador. Ya le paso tu consulta y te responde por acá en horario de atención (lunes a viernes de 9 a 18, sábados de 9 a 13).';
}
return { json: {
  caso: '#' + $execution.id,
  fecha: $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm'),
  telefono: n.telefono,
  seller: o.seller || n.nombre_perfil,
  numero_envio: numeroOk ? o.numero_envio : '',
  tipo: o.tipo || 'otro',
  prioridad: o.prioridad || 'media',
  resumen: nota + (o.resumen || ''),
  mensaje: n.texto,
  estado: 'abierto',
  origen: o.origen || (accion === 'CARGAR_CASO' ? 'agente' : 'derivado'),
  accion,
  respuesta
} };

