// Junta en un solo mail los casos abiertos de hoy.
const hoy = $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd');
const abiertos = $input.all().map(i => i.json)
  .filter(c => String(c.fecha || '').startsWith(hoy) && c.estado === 'abierto');
if (abiertos.length === 0) return [];
const orden = { alta: 0, media: 1, baja: 2 };
abiertos.sort((a, b) => (orden[a.prioridad] ?? 3) - (orden[b.prioridad] ?? 3));
const lineas = abiertos.map(c => `${c.caso} · ${c.prioridad} · ${c.tipo} · ${c.seller || c.telefono} · ${c.numero_envio || 's/n'} · ${c.resumen}`);
return [{ json: { cantidad: abiertos.length, altas: abiertos.filter(c => c.prioridad === 'alta').length, texto: lineas.join('\n') } }];
